+            .Split(documentText.Trim())
+            .Where(s => !string.IsNullOrWhiteSpace(s))
+            .ToList();
+
+        if (sentences.Count <= maxSentences)
+            return string.Join(" ", sentences);
+
+        // Build word-frequency map (excluding stop words)
+        var wordFrequency = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+        foreach (var sentence in sentences)
+        {
+            foreach (var word in TokenizeWords(sentence))
+            {
+                if (!StopWords.Contains(word))
+                    wordFrequency[word] = wordFrequency.GetValueOrDefault(word) + 1;
+            }
+        }
+
+        // Score each sentence
+        var scored = sentences
+            .Select((text, index) => (Index: index, Text: text, Score: ScoreSentence(text, wordFrequency)))
+            .ToList();
+
+        // Pick the top sentences, then restore original order
+        var topSentences = scored
+            .OrderByDescending(s => s.Score)
+            .Take(maxSentences)
+            .OrderBy(s => s.Index)
+            .Select(s => s.Text.Trim());
+
+        return string.Join(" ", topSentences);
+    }
+
+    private static double ScoreSentence(string sentence, Dictionary<string, int> wordFrequency)
+    {
+        var words = TokenizeWords(sentence);
+        if (words.Length == 0) return 0;
+
+        double score = words
+            .Where(w => !StopWords.Contains(w))
+            .Sum(w => wordFrequency.GetValueOrDefault(w));
+
+        // Normalize by word count to avoid bias toward long sentences
+        return score / words.Length;
+    }
+
+    private static string[] TokenizeWords(string text)
+    {
+        var cleaned = PunctuationStripper().Replace(text, "");
+        return cleaned.Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
+    }
+}
